import json

def solve_task():
    size = 16
    grid = [[0] * size for _ in range(size)]

    # Two patterns:
    # Pattern 1: 6,9,8 triplet along diagonal c = r + 4, r + 5, r + 6
    for r in range(size):
        for offset in [4, 5, 6]:
            c = r + offset
            if c < size:
                if offset == 4:
                    grid[r][c] = 6
                elif offset == 5:
                    grid[r][c] = 9
                elif offset == 6:
                    grid[r][c] = 8

    # Pattern 2: Single 5 along diagonal c = r - 9 (for r >= 9)
    for r in range(9, size):
        c = r - 9
        if c >= 0:
            grid[r][c] = 5

    return grid

